/// The OTLP/HTTP traces URL for `endpoint`: `/v1/traces` is appended only when the endpoint has
/// no path (or just `/`); an endpoint with a path is kept as it is (minus trailing slashes).
pub fn http_traces_endpoint(endpoint: &str) -> String {
    match url::Url::parse(endpoint) {
        Ok(url) if url.query().is_none() => {
            let base = endpoint.trim_end_matches('/');
            if url.path().trim_matches('/').is_empty() {
                format!("{base}/v1/traces")
            } else {
                base.to_string()
            }
        }
        _ => endpoint.to_string(),
    }
}

fn is_https(endpoint: &str) -> bool {
    endpoint
        .get(..8)
        .is_some_and(|p| p.eq_ignore_ascii_case("https://"))
}

